/**
 * 🎯 Customer Insights Service — AI-Powered (Gemini 2.0 Flash)
 * 
 * Generates customer insights using:
 * 1. Real company data from CSV/database (name, industry, products, location, size)
 * 2. Gemini AI for deep customer understanding (personas, pain points, buying process)
 * 3. Clearly labeled data provenance — no fabricated statistics presented as fact
 * 
 * Data provenance:
 * - "ai_analysis"     = generated by Gemini based on company + industry context
 * - "industry_data"   = derived from real company database industry stats
 * - "estimated"       = fallback when AI unavailable
 */

import { GoogleGenAI } from '@google/genai';
import { loadAllCompanies, NormalizedCompany } from './competitorEngine';

// ============================================================================
// TYPES (backward-compatible with frontend CustomerInsightsPage.tsx)
// ============================================================================

export interface IdealCustomerProfile {
    firmographics: {
        companySize: string[];
        industries: string[];
        regions: string[];
        annualRevenue: string;
        employeeCount: string;
        techMaturity: 'Early Adopter' | 'Mainstream' | 'Laggard';
    };
    decisionMakers: Array<{
        title: string;
        role: 'Economic Buyer' | 'Technical Buyer' | 'User Buyer' | 'Champion';
        concerns: string[];
        successMetrics: string[];
    }>;
    keyInfluencers: Array<{
        title: string;
        influence: 'High' | 'Medium' | 'Low';
        focus: string;
    }>;
}

export interface UserPersona {
    name: string;
    title: string;
    avatar: string;
    age: string;
    background: string;
    goals: string[];
    frustrations: string[];
    preferredChannels: string[];
    quote: string;
    dayInLife: string[];
    techStack: string[];
}

export interface PainPoint {
    category: string;
    pain: string;
    severity: 'Critical' | 'High' | 'Medium' | 'Low';
    frequency: string;
    currentSolution: string;
    costOfInaction: string;
}

export interface TriggerEvent {
    event: string;
    urgency: 'Immediate' | 'Short-term' | 'Long-term';
    likelihood: number;
    signals: string[];
    approach: string;
}

export interface BuyingStage {
    stage: string;
    description: string;
    duration: string;
    activities: string[];
    contentNeeded: string[];
    objections: string[];
    successCriteria: string;
}

export interface PurchaseBarrier {
    barrier: string;
    category: 'Price' | 'Trust' | 'Complexity' | 'Timing' | 'Politics' | 'Competition';
    severity: 'High' | 'Medium' | 'Low';
    overcomingStrategy: string;
    proofPoints: string[];
}

export interface CustomerObjection {
    objection: string;
    frequency: number;
    category: string;
    response: string;
    proofPoints: string[];
}

export interface FeatureRequest {
    feature: string;
    votes: number;
    priority: 'Critical' | 'High' | 'Medium' | 'Low';
    segment: string;
    status: 'Planned' | 'In Progress' | 'Considering' | 'Declined';
}

export interface CustomerInsightsReport {
    generatedAt: string;
    companyName: string;
    industry: string;
    dataSource: 'ai_analysis' | 'industry_data' | 'estimated';
    dataSources: string[];

    // Tier 1: Who are they?
    idealCustomerProfile: IdealCustomerProfile;
    userPersonas: UserPersona[];

    // Tier 2: Why they buy?
    painPoints: PainPoint[];
    desiredOutcomes: Array<{ outcome: string; metric: string; timeframe: string }>;
    triggerEvents: TriggerEvent[];

    // Tier 3: How they buy?
    buyingProcess: BuyingStage[];
    purchaseBarriers: PurchaseBarrier[];
    buyingCommittee: {
        avgSize: number;
        typicalCycle: string;
        budgetHolder: string;
    };

    // Tier 4: Voice of Customer
    commonObjections: CustomerObjection[];
    sentimentAnalysis: {
        overall: number;
        positive: number;
        neutral: number;
        negative: number;
        trend: 'Improving' | 'Stable' | 'Declining';
        topPositiveThemes: string[];
        topNegativeThemes: string[];
    };
    featureRequests: FeatureRequest[];
    npsScore: number;

    // Summary
    executiveSummary: {
        overview: string;
        keyInsights: string[];
        recommendations: string[];
    };
}

// ============================================================================
// GEMINI AI CLIENT
// ============================================================================

let geminiInstance: GoogleGenAI | null = null;

function getGemini(): GoogleGenAI | null {
    if (geminiInstance) return geminiInstance;
    const key = process.env.GEMINI_API_KEY;
    if (!key) {
        console.warn('⚠️ GEMINI_API_KEY not set — customer insights will use fallback data');
        return null;
    }
    geminiInstance = new GoogleGenAI({ apiKey: key });
    return geminiInstance;
}

// ============================================================================
// CACHE (30-minute TTL)
// ============================================================================

const insightsCache = new Map<string, { data: any; ts: number }>();
const CACHE_TTL = 30 * 60 * 1000;

function getCached(key: string): any | null {
    const entry = insightsCache.get(key);
    if (entry && Date.now() - entry.ts < CACHE_TTL) return entry.data;
    if (entry) insightsCache.delete(key);
    return null;
}

function setCache(key: string, data: any): void {
    insightsCache.set(key, { data, ts: Date.now() });
}

// ============================================================================
// INDUSTRY CONTEXT FROM REAL DATABASE
// ============================================================================

interface IndustryContext {
    industry: string;
    totalCompanies: number;
    avgSize: string;
    commonLocations: string[];
    sampleCompanyNames: string[];
    companySizes: string[];
}

async function buildIndustryContext(industry: string, companyName: string): Promise<IndustryContext> {
    try {
        const allCompanies = await loadAllCompanies();
        const industryCompanies = allCompanies.filter(c =>
            c.industry?.toLowerCase() === industry.toLowerCase()
        );

        const locations = new Map<string, number>();
        const sizes = new Map<string, number>();
        for (const c of industryCompanies) {
            if (c.address) {
                const city = c.address.split(',').pop()?.trim() || c.address;
                locations.set(city, (locations.get(city) || 0) + 1);
            }
            if (c.size) sizes.set(c.size, (sizes.get(c.size) || 0) + 1);
        }

        const topLocations = [...locations.entries()]
            .sort((a, b) => b[1] - a[1])
            .slice(0, 5)
            .map(([loc]) => loc);

        const topSizes = [...sizes.entries()]
            .sort((a, b) => b[1] - a[1])
            .slice(0, 4)
            .map(([s]) => s);

        const sampleNames = industryCompanies
            .filter(c => c.name.toLowerCase() !== companyName.toLowerCase())
            .slice(0, 10)
            .map(c => c.name);

        return {
            industry,
            totalCompanies: industryCompanies.length,
            avgSize: topSizes[0] || 'Unknown',
            commonLocations: topLocations.length > 0 ? topLocations : ['Ho Chi Minh City', 'Hanoi'],
            sampleCompanyNames: sampleNames,
            companySizes: topSizes
        };
    } catch {
        return {
            industry,
            totalCompanies: 0,
            avgSize: 'Unknown',
            commonLocations: ['Ho Chi Minh City', 'Hanoi'],
            sampleCompanyNames: [],
            companySizes: []
        };
    }
}

// ============================================================================
// GEMINI AI ANALYSIS
// ============================================================================

async function analyzeWithGemini(
    companyName: string,
    industry: string,
    products: string,
    targetMarket: string,
    companyData: NormalizedCompany | null,
    industryCtx: IndustryContext
): Promise<any | null> {
    const ai = getGemini();
    if (!ai) return null;

    const cacheKey = `insights:${companyName}:${industry}`.toLowerCase();
    const cached = getCached(cacheKey);
    if (cached) {
        console.log(`   📦 Cache hit for customer insights: ${companyName}`);
        return cached;
    }

    const companyContext = companyData
        ? `Company info from database:
  - Name: ${companyData.name}
  - Industry: ${companyData.industry}
  - Products/Services: ${companyData.products || products || 'N/A'}
  - Description: ${companyData.intro || 'N/A'}
  - Location: ${companyData.address || 'Vietnam'}
  - Size: ${companyData.size || 'Unknown'}
  - Website: ${companyData.website || 'N/A'}`
        : `Company: ${companyName}
  - Industry: ${industry}
  - Products: ${products || 'N/A'}
  - Market: ${targetMarket}`;

    const industryInfo = industryCtx.totalCompanies > 0
        ? `Industry context from our database of ${industryCtx.totalCompanies} ${industry} companies in Vietnam:
  - Common locations: ${industryCtx.commonLocations.join(', ')}
  - Company sizes: ${industryCtx.companySizes.join(', ')}
  - Sample companies: ${industryCtx.sampleCompanyNames.slice(0, 5).join(', ')}`
        : `Industry: ${industry} in Vietnam`;

    const prompt = `You are a B2B customer insights expert specializing in the Vietnamese market.
Analyze the potential customers of this company and generate a comprehensive customer insights report.

${companyContext}

${industryInfo}

Target Market: ${targetMarket}

Return ONLY valid JSON with this EXACT structure (use Vietnamese for all text content):
{
  "idealCustomerProfile": {
    "firmographics": {
      "companySize": ["SME (50-200)", "Mid-Market (200-1000)"],
      "industries": ["industry1", "industry2", "industry3", "industry4"],
      "regions": ["region1", "region2"],
      "annualRevenue": "revenue range",
      "employeeCount": "employee range",
      "techMaturity": "Early Adopter" or "Mainstream" or "Laggard"
    },
    "decisionMakers": [
      {
        "title": "job title",
        "role": "Economic Buyer" or "Technical Buyer" or "User Buyer" or "Champion",
        "concerns": ["concern1", "concern2", "concern3"],
        "successMetrics": ["metric1", "metric2", "metric3"]
      }
    ],
    "keyInfluencers": [
      {"title": "title", "influence": "High" or "Medium" or "Low", "focus": "focus area"}
    ]
  },
  "userPersonas": [
    {
      "name": "Vietnamese name with alliterative role prefix",
      "title": "job title",
      "avatar": "emoji",
      "age": "age range",
      "background": "background in Vietnamese",
      "goals": ["goal1", "goal2", "goal3"],
      "frustrations": ["frustration1", "frustration2", "frustration3"],
      "preferredChannels": ["channel1", "channel2", "channel3"],
      "quote": "characteristic quote in Vietnamese",
      "dayInLife": ["activity1", "activity2", "activity3"],
      "techStack": ["tool1", "tool2", "tool3"]
    }
  ],
  "painPoints": [
    {
      "category": "category",
      "pain": "specific pain point relevant to ${companyName}'s customers in Vietnamese",
      "severity": "Critical" or "High" or "Medium" or "Low",
      "frequency": "how often",
      "currentSolution": "what they do now",
      "costOfInaction": "cost of not solving"
    }
  ],
  "desiredOutcomes": [
    {"outcome": "outcome in Vietnamese", "metric": "measurable metric", "timeframe": "timeframe"}
  ],
  "triggerEvents": [
    {
      "event": "trigger event",
      "urgency": "Immediate" or "Short-term" or "Long-term",
      "likelihood": 70,
      "signals": ["signal1", "signal2"],
      "approach": "sales approach in Vietnamese"
    }
  ],
  "buyingProcess": [
    {
      "stage": "stage name in Vietnamese",
      "description": "description in Vietnamese",
      "duration": "duration",
      "activities": ["activity1", "activity2"],
      "contentNeeded": ["content1", "content2"],
      "objections": ["objection1"],
      "successCriteria": "criteria in Vietnamese"
    }
  ],
  "purchaseBarriers": [
    {
      "barrier": "barrier in Vietnamese",
      "category": "Price" or "Trust" or "Complexity" or "Timing" or "Politics" or "Competition",
      "severity": "High" or "Medium" or "Low",
      "overcomingStrategy": "strategy in Vietnamese",
      "proofPoints": ["proof1", "proof2"]
    }
  ],
  "buyingCommittee": {
    "avgSize": 4,
    "typicalCycle": "X ngày",
    "budgetHolder": "job title"
  },
  "commonObjections": [
    {
      "objection": "objection in Vietnamese",
      "frequency": 75,
      "category": "Price or Usability or Competition or Timing or Implementation",
      "response": "detailed response in Vietnamese",
      "proofPoints": ["proof1", "proof2"]
    }
  ],
  "sentimentAnalysis": {
    "overall": 7.5,
    "positive": 55,
    "neutral": 30,
    "negative": 15,
    "trend": "Improving" or "Stable" or "Declining",
    "topPositiveThemes": ["theme1", "theme2", "theme3"],
    "topNegativeThemes": ["theme1", "theme2"]
  },
  "featureRequests": [
    {
      "feature": "feature name",
      "votes": 150,
      "priority": "Critical" or "High" or "Medium" or "Low",
      "segment": "segment",
      "status": "Planned" or "In Progress" or "Considering" or "Declined"
    }
  ],
  "npsScore": 45,
  "executiveSummary": {
    "overview": "2-3 sentence overview in Vietnamese about ${companyName}'s customer landscape",
    "keyInsights": ["insight1", "insight2", "insight3", "insight4", "insight5"],
    "recommendations": ["recommendation1", "recommendation2", "recommendation3"]
  }
}

IMPORTANT RULES:
- Generate 3 personas specific to ${companyName}'s likely customers in Vietnam
- Generate 4-6 pain points specific to what ${companyName} solves
- Generate 5 buying process stages specific to ${industry} in Vietnam
- Generate 4-5 purchase barriers relevant to Vietnam B2B
- Generate 5-6 common objections with realistic frequencies (50-90)
- Sentiment: reflect typical ${industry} B2B landscape based on your knowledge (not real survey data — note this)
- NPS: industry benchmarks for ${industry} in Vietnam (30-60 range)
- Feature requests: realistic for ${companyName}'s product type, votes 50-250
- All text content in Vietnamese
- Be specific to ${companyName} — do NOT use generic templates
- 3-4 decision makers, 2-3 key influencers`;

    const MAX_RETRIES = 2;
    for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
        try {
            const response = await ai.models.generateContent({
                model: 'gemini-2.0-flash',
                contents: prompt,
                config: {
                    temperature: 0.4,
                    maxOutputTokens: 4000,
                }
            });

            const text = response.text || '';
            const jsonMatch = text.match(/\{[\s\S]*\}/);
            if (!jsonMatch) {
                console.warn(`   ⚠️ Gemini returned non-JSON for customer insights`);
                return null;
            }

            const parsed = JSON.parse(jsonMatch[0]);
            setCache(cacheKey, parsed);
            console.log(`   🤖 AI customer insights generated for: ${companyName}`);
            return parsed;
        } catch (err: any) {
            const is429 = err?.status === 429 || err?.message?.includes('429') || err?.message?.includes('quota');
            if (is429 && attempt < MAX_RETRIES) {
                const delay = (attempt + 1) * 5000;
                console.warn(`   ⏳ Gemini rate-limited, retry ${attempt + 1}/${MAX_RETRIES} in ${delay / 1000}s...`);
                await new Promise(r => setTimeout(r, delay));
                continue;
            }
            console.error(`   ❌ Gemini customer insights error:`, err?.message || err);
            return null;
        }
    }
    return null;
}

