        'Finance': ['Banking', 'Insurance', 'Investment', 'Payment', 'Lending'],
        'Retail': ['FMCG', 'Fashion', 'Electronics', 'Food & Beverage', 'Home'],
        'Education': ['K-12', 'University', 'EdTech', 'Corporate Training', 'Online Learning'],
        'Healthcare': ['Hospital', 'Clinic', 'Pharma', 'Medical Device', 'Telehealth'],
