// ============================================================================
// MAIN EXPORT
// ============================================================================

export async function generateCustomerInsights(params: {
    companyName: string;
    industry?: string;
    products?: string;
    targetMarket?: string;
}): Promise<CustomerInsightsReport> {
    const { companyName, industry = 'Technology', products = '', targetMarket = 'Vietnam' } = params;

    console.log(`🎯 Customer Insights Request: ${companyName} (${industry})`);

    // 1. Find company in database
    let companyData: NormalizedCompany | null = null;
    try {
        const allCompanies = await loadAllCompanies();
        companyData = allCompanies.find(c =>
            c.name.toLowerCase().includes(companyName.toLowerCase()) ||
            companyName.toLowerCase().includes(c.name.toLowerCase())
        ) || null;
        if (companyData) {
            console.log(`   📊 Found company in database: ${companyData.name} (${companyData.industry})`);
        }
    } catch (err) {
        console.warn('   ⚠️ Could not load company database');
    }

    const detectedIndustry = companyData?.industry || industry;

    // 2. Build industry context from real database
    const industryCtx = await buildIndustryContext(detectedIndustry, companyName);
    console.log(`   📈 Industry context: ${industryCtx.totalCompanies} companies in ${detectedIndustry}`);

    // 3. Try AI analysis
    const aiInsights = await analyzeWithGemini(
        companyName, detectedIndustry, products, targetMarket, companyData, industryCtx
    );

    if (aiInsights) {
        // Successfully generated AI insights — map to typed report
        const report: CustomerInsightsReport = {
            generatedAt: new Date().toISOString(),
            companyName,
            industry: detectedIndustry,
            dataSource: 'ai_analysis',
            dataSources: [
                companyData ? 'VICO Company Database' : 'User input',
                'Gemini 2.0 Flash AI Analysis',
                industryCtx.totalCompanies > 0 ? `Industry data (${industryCtx.totalCompanies} companies)` : ''
            ].filter(Boolean),

            idealCustomerProfile: {
                firmographics: {
                    ...aiInsights.idealCustomerProfile.firmographics,
                    techMaturity: (aiInsights.idealCustomerProfile.firmographics.techMaturity as any) || 'Mainstream'
                },
                decisionMakers: (aiInsights.idealCustomerProfile.decisionMakers || []).map((dm: any) => ({
                    ...dm,
                    role: dm.role as any || 'Champion'
                })),
                keyInfluencers: (aiInsights.idealCustomerProfile.keyInfluencers || []).map((ki: any) => ({
                    ...ki,
                    influence: ki.influence as any || 'Medium'
                }))
            },
            userPersonas: aiInsights.userPersonas || [],

            painPoints: (aiInsights.painPoints || []).map((pp: any) => ({
                ...pp,
                severity: pp.severity as any || 'Medium'
            })),
            desiredOutcomes: aiInsights.desiredOutcomes || [],
            triggerEvents: (aiInsights.triggerEvents || []).map((te: any) => ({
                ...te,
                urgency: te.urgency as any || 'Short-term'
            })),

            buyingProcess: aiInsights.buyingProcess || [],
            purchaseBarriers: (aiInsights.purchaseBarriers || []).map((pb: any) => ({
                ...pb,
                category: pb.category as any || 'Complexity',
                severity: pb.severity as any || 'Medium'
            })),
            buyingCommittee: aiInsights.buyingCommittee || { avgSize: 4, typicalCycle: '60 ngày', budgetHolder: 'CEO' },

            commonObjections: aiInsights.commonObjections || [],
            sentimentAnalysis: {
                overall: aiInsights.sentimentAnalysis?.overall || 0,
                positive: aiInsights.sentimentAnalysis?.positive || 0,
                neutral: aiInsights.sentimentAnalysis?.neutral || 0,
                negative: aiInsights.sentimentAnalysis?.negative || 0,
                trend: (aiInsights.sentimentAnalysis?.trend as any) || 'Stable',
                topPositiveThemes: aiInsights.sentimentAnalysis?.topPositiveThemes || [],
                topNegativeThemes: aiInsights.sentimentAnalysis?.topNegativeThemes || []
            },
            featureRequests: (aiInsights.featureRequests || []).map((fr: any) => ({
                ...fr,
                priority: fr.priority as any || 'Medium',
                status: fr.status as any || 'Considering'
            })),
            npsScore: aiInsights.npsScore || 0,

            executiveSummary: aiInsights.executiveSummary || {
                overview: `Phân tích AI cho ${companyName}`,
                keyInsights: [],
                recommendations: []
            }
        };

        console.log(`✅ Customer Insights generated via AI for ${companyName}`);
        return report;
    }

    // 4. Fallback when AI unavailable
    console.log(`   ⚠️ Using fallback insights for ${companyName} (AI unavailable)`);
    return buildFallbackReport(companyName, detectedIndustry, products, targetMarket, industryCtx);
}

export default generateCustomerInsights;
